{
    "schema_version": 1,
    "json_schema": {
        "builder": {
            "$defs": {
                "AllGroup": {
                    "additionalProperties": false,
                    "properties": {
                        "all": {
                            "description": "AND: every child is true",
                            "items": {
                                "oneOf": [
                                    {
                                        "$ref": "#/$defs/AllGroup"
                                    },
                                    {
                                        "$ref": "#/$defs/AnyGroup"
                                    },
                                    {
                                        "$ref": "#/$defs/CompareCondition"
                                    },
                                    {
                                        "$ref": "#/$defs/BetweenCondition"
                                    },
                                    {
                                        "$ref": "#/$defs/TrendCondition"
                                    }
                                ]
                            },
                            "minItems": 1,
                            "title": "All",
                            "type": "array"
                        }
                    },
                    "required": [
                        "all"
                    ],
                    "title": "AllGroup",
                    "type": "object"
                },
                "AnyGroup": {
                    "additionalProperties": false,
                    "properties": {
                        "any": {
                            "description": "OR: at least one child is true",
                            "items": {
                                "oneOf": [
                                    {
                                        "$ref": "#/$defs/AllGroup"
                                    },
                                    {
                                        "$ref": "#/$defs/AnyGroup"
